(function(E){ E["ai-internet-tools"] = {"meta":{"checkedOn":"2026-10-31","asOf":{"en":"As of October 2026. Tools change.","tr":"Ekim 2026 itibarıyla. Araçlar değişebilir.","fa":"به‌روز تا اکتبر ۲۰۲۶. ابزارها تغییر می‌کنند."},"shared":[{"where":"Top of each guide","t":{"en":"As of [month year]. Tools change.","tr":"[Ay yıl] itibarıyla. Araçlar değişebilir.","fa":"به‌روز تا [ماه سال]. ابزارها تغییر می‌کنند."}},{"where":"Under \"How to start\"","t":{"en":"If it doesn't open, or you don't want an account, that's fine. The practice in this lesson uses fixed examples, so the task is the same.","tr":"Açılmıyorsa ya da hesap açmak istemiyorsan sorun değil. Bu dersin uygulamasında sabit örnekler var, yani görev aynı.","fa":"اگر باز نمی‌شود یا نمی‌خواهی حساب بسازی، اشکالی ندارد. تمرین‌های این درس نمونه‌های آماده دارند، پس کار همان است."}},{"where":"Under \"How to start\"","t":{"en":"Each maker has its own rules on age and country. Read them before you sign up.","tr":"Her şirketin yaş ve ülke konusunda kendi kuralları vardır. Kaydolmadan önce oku.","fa":"هر شرکت درباره‌ی سن و کشور قواعد خودش را دارد. پیش از ثبت‌نام آن‌ها را بخوان."}},{"where":"Above the words","t":{"en":"Names can differ on your screen. Look for the idea, not the exact word.","tr":"Ekranındaki adlar farklı olabilir. Tam kelimeyi değil, fikri ara.","fa":"نام‌ها ممکن است روی صفحه‌ی تو فرق داشته باشند. دنبال معنی بگرد، نه خود کلمه."}},{"where":"Under \"Limits\"","t":{"en":"Model names change often. You don't need to learn them.","tr":"Model adları sık sık değişir. Bunları öğrenmen gerekmez.","fa":"نام مدل‌ها زیاد عوض می‌شود. لازم نیست یادشان بگیری."}},{"where":"Under \"Limits\"","t":{"en":"Never paste passwords, customer details or company secrets. Follow your company's rule first.","tr":"Parolaları, müşteri bilgilerini ya da şirket sırlarını asla yapıştırma. Önce şirketinin kuralına uy.","fa":"هرگز رمز عبور، اطلاعات مشتری یا اسرار شرکت را نچسبان. اول به مقررات شرکتت عمل کن."}},{"where":"End of the lesson's tool screens","t":{"en":"No account, or it doesn't open? That's fine: the practice in this lesson uses fixed examples. More words and prompts are in this tool's guide.","tr":"Hesabın yok ya da açılmıyor mu? Sorun değil: Bu dersin uygulamasında sabit örnekler var. Diğer kelimeler ve prompt'lar bu aracın rehberinde.","fa":"حساب نداری یا باز نمی‌شود؟ اشکالی ندارد: تمرین‌های این درس نمونه‌های آماده دارند. کلمه‌ها و پرامپت‌های بیشتر در راهنمای این ابزار هستند."}}],"messages":[{"msg":"Limit reached / Too many requests","mean":{"en":"You used too much for now. Wait and try later.","tr":"Şimdilik çok kullandın. Bekle, sonra yeniden dene.","fa":"فعلاً زیاد استفاده کرده‌ای. صبر کن و بعداً دوباره امتحان کن."}},{"msg":"File too large","mean":{"en":"The file is over the limit. Make it smaller or paste a part.","tr":"Dosya sınırın üstünde. Küçült ya da bir bölümünü yapıştır.","fa":"فایل از حد مجاز بزرگ‌تر است. کوچکش کن یا بخشی از آن را بچسبان."}},{"msg":"Something went wrong","mean":{"en":"The tool had a problem. Try again.","tr":"Araçta bir sorun oldu. Yeniden dene.","fa":"ابزار دچار مشکل شده. دوباره امتحان کن."}},{"msg":"Not available in your region","mean":{"en":"The tool isn't offered there. In this course, continue with the fixed examples.","tr":"Araç orada sunulmuyor. Bu kursta sabit örneklerle devam et.","fa":"این ابزار آنجا ارائه نمی‌شود. در این دوره با نمونه‌های آماده ادامه بده."}},{"msg":"Blocked by policy / I can't help with that","mean":{"en":"The tool refused the request. Say honestly what you need, or do the task another way.","tr":"Araç isteği reddetti. Neye ihtiyacın olduğunu dürüstçe söyle ya da işi başka yoldan yap.","fa":"ابزار درخواست را رد کرده. صادقانه بگو چه می‌خواهی یا کار را از راه دیگری انجام بده."}}]},"tools":{"chatgpt":{"id":"chatgpt","name":"ChatGPT","lesson":2,"checkedOn":"2026-10-31","source":"OUTLINE.md section 2.9","line":{"en":"A general assistant for writing, questions and many small jobs.","tr":"Yazı, sorular ve birçok küçük iş için genel bir asistan.","fa":"یک دستیار عمومی برای نوشتن، پرسیدن و خیلی از کارهای کوچک."},"what":{"en":"ChatGPT is a general AI assistant made by the company OpenAI. You write a message and it answers in the same chat. It can write, explain, search the web, read files and make images.","tr":"ChatGPT, OpenAI şirketinin yaptığı genel bir yapay zekâ asistanıdır. Bir mesaj yazarsın, aynı sohbette yanıt verir. Yazı yazabilir, açıklayabilir, web'de arama yapabilir, dosya okuyabilir ve görsel üretebilir.","fa":"ChatGPT یک دستیار عمومی هوش مصنوعی است که شرکت OpenAI آن را ساخته. پیامی می‌نویسی و در همان چت جواب می‌دهد. می‌تواند بنویسد، توضیح بدهد، در وب جست‌وجو کند، فایل بخواند و تصویر بسازد."},"teach":[{"en":"It remembers what you said earlier in the same chat, so you can simply ask for changes.","tr":"Aynı sohbette daha önce söylediklerini hatırlar; değişikliği doğrudan isteyebilirsin.","fa":"حرف‌های قبلی‌ات را در همان چت به یاد دارد، پس می‌توانی به‌سادگی تغییر بخواهی.","ex":"Shorter, please. Keep the date."},{"en":"New chat starts with a clean page. Use it for a new topic.","tr":"New chat temiz bir sayfayla başlar. Yeni bir konu için kullan.","fa":"New chat با صفحه‌ای خالی شروع می‌شود. برای موضوع جدید از آن استفاده کن.","ex":"New chat"}],"good":[{"en":"First drafts and rewrites of emails and short texts","tr":"E-posta ve kısa metinlerin ilk taslakları ve yeniden yazımı","fa":"پیش‌نویس اول و بازنویسی ایمیل و متن‌های کوتاه","ex":"Rewrite this email in plain English."},{"en":"Explaining a hard text in simple words","tr":"Zor bir metni basit kelimelerle açıklamak","fa":"توضیح دادن یک متن سخت با کلمه‌های ساده","ex":"Explain this contract line in simple words."},{"en":"Ideas and plans","tr":"Fikirler ve planlar","fa":"ایده و برنامه"},{"en":"Many small jobs in one place, including a picture in the chat","tr":"Birçok küçük işi tek yerde yapmak, sohbette görsel üretmek dahil","fa":"انجام خیلی از کارهای کوچک در یک جا، حتی ساختن تصویر در چت"}],"notBest":[{"en":"A fact you won't check. OpenAI warns it can give wrong facts and invented references.","tr":"Kontrol etmeyeceğin bir bilgi. OpenAI, yanlış bilgi ve uydurma kaynak verebileceği konusunda uyarıyor.","fa":"اطلاعاتی که قرار نیست بررسی‌اش کنی. خود OpenAI هشدار می‌دهد که ممکن است اطلاعات غلط و منبع ساختگی بدهد.","ex":"Invented references can look real."},{"en":"Private customer or company information","tr":"Özel müşteri ya da şirket bilgileri","fa":"اطلاعات خصوصی مشتری یا شرکت","ex":"Customer lists, contracts, passwords"}],"start":[{"en":"Go to chatgpt.com.","tr":"chatgpt.com adresine git.","fa":"به chatgpt.com برو."},{"en":"Sign up or log in.","tr":"Kaydol ya da giriş yap.","fa":"ثبت‌نام کن یا وارد شو."},{"en":"Type in the message box and send.","tr":"Mesaj kutusuna yaz ve gönder.","fa":"در کادر پیام بنویس و بفرست."},{"en":"Read the answer. Ask for changes in the same chat.","tr":"Yanıtı oku. Değişiklikleri aynı sohbette iste.","fa":"جواب را بخوان. تغییرها را در همان چت بخواه."}],"startNote":{"en":"There is a free plan. Files, images and voice have their own limits, and these can change.","tr":"Ücretsiz bir plan var. Dosya, görsel ve sesin kendi sınırları vardır ve bunlar değişebilir.","fa":"یک پلن رایگان هست. فایل، تصویر و صدا محدودیت‌های خودشان را دارند و این محدودیت‌ها ممکن است تغییر کنند."},"words":[{"word":"New chat","meaning":{"en":"Start again, with no earlier messages in this chat","tr":"Yeniden başla, bu sohbette önceki mesajlar olmadan","fa":"از نو شروع کن، بدون پیام‌های قبلی در این چت"}},{"word":"Search","meaning":{"en":"Ask it to look on the web","tr":"Web'de bakmasını iste","fa":"از آن بخواه در وب بگردد"}},{"word":"Sources","meaning":{"en":"The list of links behind an answer","tr":"Bir yanıtın dayandığı bağlantıların listesi","fa":"فهرست لینک‌هایی که جواب بر اساس آن‌هاست"}},{"word":"Temporary Chat","meaning":{"en":"A chat that stays out of your history and isn't used to improve the models","tr":"Geçmişinde görünmeyen ve modelleri geliştirmek için kullanılmayan sohbet","fa":"چتی که در تاریخچه‌ات نمی‌ماند و برای بهتر کردن مدل‌ها استفاده نمی‌شود"}},{"word":"Settings","meaning":{"en":"Where you change how it works","tr":"Nasıl çalıştığını değiştirdiğin yer","fa":"جایی که شیوه‌ی کارش را تغییر می‌دهی"}},{"word":"Data controls","meaning":{"en":"Settings about your data","tr":"Verilerinle ilgili ayarlar","fa":"تنظیمات مربوط به داده‌هایت"}},{"word":"Improve the model for everyone","meaning":{"en":"Allows your chats to be used for training. On personal plans it is on until you turn it off.","tr":"Sohbetlerinin model eğitiminde kullanılmasına izin verir. Kişisel planlarda sen kapatana kadar açıktır.","fa":"اجازه می‌دهد چت‌هایت برای آموزش مدل استفاده شوند. در پلن‌های شخصی تا خودت خاموشش نکنی روشن است."}}],"prompts":[{"text":"Rewrite this email in plain English for a customer who is not technical.\nKeep every number and date. Under 100 words.\nThen list what you changed.\nEmail: [paste the email, with private details removed]","why":{"en":"It is good at rewriting, and the last line lets you check its changes.","tr":"Yeniden yazmada iyidir, son satır da değişikliklerini kontrol etmeni sağlar.","fa":"در بازنویسی خوب است و خط آخر کمک می‌کند تغییرهایش را بررسی کنی."},"run":false},{"text":"Search the web: what is the warranty period for [product]?\nGive three sources with links and dates.\nIf you cannot find it, write \"not found\".","why":{"en":"\"Search\" makes it look on the web. Then you open the links yourself.","tr":"\"Search\" web'e bakmasını sağlar. Sonra bağlantıları kendin açarsın.","fa":"با «Search» در وب می‌گردد. بعد لینک‌ها را خودت باز می‌کنی."},"run":false}],"limits":[{"en":"It can sound sure and still be wrong. It can even invent a reference.","tr":"Emin görünüp yine de yanılabilir. Uydurma bir kaynak bile verebilir.","fa":"ممکن است مطمئن به نظر برسد و باز هم اشتباه کند. حتی ممکن است منبع ساختگی بدهد."},{"en":"The same prompt can give a different answer each time.","tr":"Aynı prompt her seferinde farklı bir yanıt verebilir.","fa":"یک پرامپت ممکن است هر بار جواب متفاوتی بدهد."},{"en":"A Temporary Chat is not a place for secrets. The rule about private data stays the same.","tr":"Temporary Chat sırlar için bir yer değildir. Özel bilgi kuralı aynen geçerlidir.","fa":"Temporary Chat جای اطلاعات محرمانه نیست. قاعده‌ی اطلاعات خصوصی همان است."}]},"gemini":{"id":"gemini","name":"Gemini","lesson":3,"checkedOn":"2026-10-31","source":"OUTLINE.md section 2.9","line":{"en":"Google's assistant. Look at it if your work is in Gmail, Docs and Drive.","tr":"Google'ın asistanı. İşin Gmail, Docs ve Drive'daysa ona bak.","fa":"دستیار گوگل. اگر کارت در Gmail، Docs و Drive است، سراغش برو."},"what":{"en":"Gemini is the AI assistant from Google. You chat with it at gemini.google.com or in its app.","tr":"Gemini, Google'ın yapay zekâ asistanıdır. gemini.google.com adresinde ya da uygulamasında onunla sohbet edersin.","fa":"Gemini دستیار هوش مصنوعی گوگل است. در gemini.google.com یا اپلیکیشنش با آن چت می‌کنی."},"teach":[{"en":"It can work with your Gmail and Drive, but only if you connect them.","tr":"Gmail ve Drive'ınla çalışabilir, ama yalnızca sen bağlarsan.","fa":"می‌تواند با Gmail و Drive تو کار کند، ولی فقط اگر خودت وصلشان کنی.","ex":"Connected Apps"},{"en":"People may review some chats, so decide what you paste.","tr":"Bazı sohbetleri insanlar inceleyebilir; bu yüzden neyi yapıştıracağına karar ver.","fa":"ممکن است افرادی بعضی چت‌ها را بازبینی کنند، پس تصمیم بگیر چه چیزی را بچسبانی.","ex":"Keep activity"}],"good":[{"en":"Work that is already in Gmail, Docs or Drive","tr":"Zaten Gmail, Docs ya da Drive'da olan işler","fa":"کارهایی که همین حالا در Gmail، Docs یا Drive هستند","ex":"Summarise this month's emails about the move."},{"en":"Short summaries of hard topics, and first drafts","tr":"Zor konuların kısa özetleri ve ilk taslaklar","fa":"خلاصه‌ی کوتاه موضوع‌های سخت و پیش‌نویس اول"},{"en":"Making files such as documents, spreadsheets and PDFs","tr":"Belge, tablo ve PDF gibi dosyalar hazırlamak","fa":"ساختن فایل‌هایی مثل سند، جدول و PDF","ex":"Turn my notes into a one-page document."},{"en":"A longer report with Deep Research","tr":"Deep Research ile daha uzun bir rapor","fa":"یک گزارش طولانی‌تر با Deep Research"}],"notBest":[{"en":"Work that all lives in Microsoft files. Look at Copilot.","tr":"Tamamı Microsoft dosyalarında olan işler. Copilot'a bak.","fa":"کاری که همه‌اش در فایل‌های مایکروسافت است. سراغ Copilot برو.","ex":"Word and Excel files: look at Copilot."},{"en":"Confidential information. Google says not to enter anything you wouldn't want a reviewer to see.","tr":"Gizli bilgiler. Google, bir incelemecinin görmesini istemeyeceğin hiçbir şeyi girmemeni söylüyor.","fa":"اطلاعات محرمانه. گوگل می‌گوید چیزی را که نمی‌خواهی یک بازبین ببیند وارد نکن.","ex":"Would you show it to a stranger?"}],"start":[{"en":"Go to gemini.google.com.","tr":"gemini.google.com adresine git.","fa":"به gemini.google.com برو."},{"en":"Some features work without signing in. For more, sign in with a Google account.","tr":"Bazı özellikler giriş yapmadan çalışır. Daha fazlası için Google hesabınla giriş yap.","fa":"بعضی امکانات بدون ورود کار می‌کنند. برای امکانات بیشتر با حساب گوگلت وارد شو."},{"en":"Type in the box at the bottom, then press Submit.","tr":"Alttaki kutuya yaz, sonra Submit'e bas.","fa":"در کادر پایین بنویس و بعد Submit را بزن."},{"en":"To start again, press New chat. If you can't see it, press Menu first.","tr":"Yeniden başlamak için New chat'e bas. Göremiyorsan önce Menu'ye bas.","fa":"برای شروع دوباره New chat را بزن. اگر آن را نمی‌بینی، اول Menu را بزن."}],"startNote":{"en":"Your limit depends on how much you use and on your plan.","tr":"Sınırın, ne kadar kullandığına ve planına bağlıdır.","fa":"محدودیتت به مقدار استفاده و پلنت بستگی دارد."},"words":[{"word":"Add files","meaning":{"en":"Add a file or picture","tr":"Dosya ya da görsel ekle","fa":"فایل یا تصویر اضافه کن"}},{"word":"Submit","meaning":{"en":"Send your message","tr":"Mesajını gönder","fa":"پیامت را بفرست"}},{"word":"Keep activity","meaning":{"en":"Saves your chats in your activity. They can be used to improve Google's services, and people may review some of them.","tr":"Sohbetlerini etkinliğine kaydeder. Google hizmetlerini geliştirmek için kullanılabilirler ve bazılarını insanlar inceleyebilir.","fa":"چت‌هایت را در فعالیتت نگه می‌دارد. ممکن است برای بهتر کردن سرویس‌های گوگل استفاده شوند و بعضی از آن‌ها را افرادی بازبینی کنند."}},{"word":"Temporary chat","meaning":{"en":"A chat kept only for a short time and not used to train the AI models","tr":"Yalnızca kısa süre saklanan ve yapay zekâ modellerini eğitmek için kullanılmayan sohbet","fa":"چتی که فقط مدت کوتاهی نگه داشته می‌شود و برای آموزش مدل‌ها استفاده نمی‌شود"}},{"word":"Connected Apps","meaning":{"en":"Lets Gemini use other services, such as Gmail, with your permission","tr":"İzninle Gemini'ın Gmail gibi başka hizmetleri kullanmasını sağlar","fa":"با اجازه‌ی تو، Gemini می‌تواند از سرویس‌های دیگر مثل Gmail استفاده کند"}},{"word":"Deep Research","meaning":{"en":"Searches many sources and writes a longer report","tr":"Birçok kaynağı tarar ve daha uzun bir rapor yazar","fa":"منبع‌های زیادی را می‌گردد و گزارش طولانی‌تری می‌نویسد"}},{"word":"Help me write","meaning":{"en":"A writing helper inside Gmail and Docs","tr":"Gmail ve Docs içindeki yazma yardımcısı","fa":"کمک‌نویس داخل Gmail و Docs"}}],"prompts":[{"text":"Turn my notes below into a one-page document with three headings:\nGoal, Decisions, Next steps.\nUse only my notes. If something is unclear, list it at the end.\nNotes: [paste notes, with names replaced by [Customer] or [Colleague]]","why":{"en":"It can make documents, and placeholders keep names out.","tr":"Belge hazırlayabilir, yer tutucular da adları dışarıda tutar.","fa":"می‌تواند سند بسازد و جای‌نگهدارها نمی‌گذارند نام‌ها وارد ابزار شوند."},"run":false},{"text":"Find the emails from this month about [project] in my Gmail.\nMake a table: decision, open question, who owns it.\nShow the date of each email so I can check it.","why":{"en":"It can read Gmail through Connected Apps. Use this only if you are signed in, and only if your company allows it.","tr":"Connected Apps üzerinden Gmail'i okuyabilir. Bunu yalnızca giriş yaptıysan ve şirketin izin veriyorsa kullan.","fa":"از راه Connected Apps می‌تواند Gmail را بخواند. فقط وقتی از این استفاده کن که وارد شده‌ای و شرکتت اجازه می‌دهد."},"run":false}],"limits":[{"en":"Google says Gemini can make mistakes, so double-check its answers.","tr":"Google, Gemini'ın hata yapabileceğini söylüyor. Bu yüzden yanıtlarını iki kez kontrol et.","fa":"گوگل می‌گوید Gemini ممکن است اشتباه کند، پس جواب‌هایش را دوباره بررسی کن."},{"en":"Turning off Keep activity doesn't remove chats that people have already reviewed.","tr":"Keep activity'yi kapatmak, insanların zaten incelediği sohbetleri silmez.","fa":"خاموش کردن Keep activity چت‌هایی را که بازبین‌ها قبلاً دیده‌اند پاک نمی‌کند."},{"en":"A temporary chat is still kept for a short time. A setting is not a guarantee, so remove private details first.","tr":"Temporary chat de kısa süre saklanır. Ayar bir güvence değildir, bu yüzden önce özel bilgileri çıkar.","fa":"چت موقت هم مدت کوتاهی نگه داشته می‌شود. تنظیمات تضمین نیستند، پس اول اطلاعات خصوصی را حذف کن."}]},"copilot":{"id":"copilot","name":"Copilot","lesson":4,"checkedOn":"2026-10-31","source":"OUTLINE.md section 2.9","line":{"en":"Microsoft's assistant. Look at it if your work is in Word, Excel and Outlook.","tr":"Microsoft'un asistanı. İşin Word, Excel ve Outlook'taysa ona bak.","fa":"دستیار مایکروسافت. اگر کارت در Word، Excel و Outlook است، سراغش برو."},"what":{"en":"Copilot is the AI assistant from Microsoft. You can use it in two ways: as a chat, or inside programs such as Word, Excel, PowerPoint, Outlook and Teams.","tr":"Copilot, Microsoft'un yapay zekâ asistanıdır. İki şekilde kullanabilirsin: sohbet olarak ya da Word, Excel, PowerPoint, Outlook ve Teams gibi programların içinde.","fa":"Copilot دستیار هوش مصنوعی مایکروسافت است. از دو راه می‌توانی از آن استفاده کنی: به‌صورت چت، یا داخل برنامه‌هایی مثل Word، Excel، PowerPoint، Outlook و Teams."},"teach":[{"en":"In the chat, you can ask about anything.","tr":"Sohbette her şeyi sorabilirsin.","fa":"در چت می‌توانی درباره‌ی هر چیزی بپرسی.","ex":"What does \"net 30\" mean on an invoice?"},{"en":"Inside Word, Outlook or Excel, it can work on the open file, if your plan includes it.","tr":"Word, Outlook ya da Excel içinde, planın kapsıyorsa açık dosya üzerinde çalışabilir.","fa":"داخل Word، Outlook یا Excel، اگر پلنت شامل آن باشد، می‌تواند روی فایل باز کار کند.","ex":"Summarize this thread."}],"good":[{"en":"Drafting a letter or changing its tone in Word","tr":"Word'de mektup taslağı hazırlamak ya da üslubunu değiştirmek","fa":"نوشتن پیش‌نویس نامه یا تغییر لحن آن در Word","ex":"Draft a reply. Make the tone friendlier."},{"en":"Summarising a long email thread in Outlook","tr":"Outlook'ta uzun bir e-posta zincirini özetlemek","fa":"خلاصه کردن یک رشته ایمیل طولانی در Outlook","ex":"Summarize this thread for my manager."},{"en":"Questions about a table in Excel","tr":"Excel'deki bir tablo hakkında sorular","fa":"سؤال درباره‌ی یک جدول در Excel","ex":"Which product sold most in May?"},{"en":"Longer jobs, using its agents","tr":"Agent'larıyla daha uzun işler","fa":"کارهای طولانی‌تر با ایجنت‌هایش"}],"notBest":[{"en":"Work that isn't in Microsoft programs. The chat still helps, but you lose its main advantage.","tr":"Microsoft programlarında olmayan işler. Sohbet yine yardımcı olur ama asıl avantajını kaybedersin.","fa":"کاری که در برنامه‌های مایکروسافت نیست. چت باز هم کمک می‌کند، ولی مزیت اصلی‌اش را از دست می‌دهی.","ex":"Mail in Gmail? Look at Gemini."},{"en":"Using it inside Word or Excel with no suitable plan. That part goes with certain Microsoft 365 plans.","tr":"Uygun bir plan olmadan Word ya da Excel içinde kullanmak. Bu bölüm belirli Microsoft 365 planlarıyla gelir.","fa":"استفاده داخل Word یا Excel بدون پلن مناسب. این بخش فقط با بعضی پلن‌های Microsoft 365 می‌آید."}],"start":[{"en":"Go to Microsoft's Copilot page, or open the Copilot app.","tr":"Microsoft'un Copilot sayfasına git ya da Copilot uygulamasını aç.","fa":"به صفحه‌ی Copilot مایکروسافت برو یا اپلیکیشن Copilot را باز کن."},{"en":"Sign in with a Microsoft account, or create one.","tr":"Microsoft hesabınla giriş yap ya da hesap oluştur.","fa":"با حساب مایکروسافتت وارد شو یا یکی بساز."},{"en":"Write your goal first, then add the other parts.","tr":"Önce hedefini yaz, sonra diğer bölümleri ekle.","fa":"اول هدفت را بنویس و بعد بخش‌های دیگر را اضافه کن."},{"en":"At work: ask your company what you can use. A work account has its own data rules.","tr":"İşte: Neyi kullanabileceğini şirketine sor. İş hesabının kendi veri kuralları vardır.","fa":"در محل کار: از شرکتت بپرس از چه چیزی می‌توانی استفاده کنی. حساب کاری قواعد خودش را برای داده‌ها دارد."}],"startNote":null,"words":[{"word":"Sign in","meaning":{"en":"Enter your account","tr":"Hesabına giriş yap","fa":"وارد حسابت شو"}},{"word":"Chat","meaning":{"en":"Ask questions and get answers","tr":"Soru sor, yanıt al","fa":"سؤال بپرس و جواب بگیر"}},{"word":"Agents","meaning":{"en":"Helpers that can do several steps of a job","tr":"Bir işin birkaç adımını yapabilen yardımcılar","fa":"دستیارهایی که می‌توانند چند مرحله از یک کار را انجام بدهند"}},{"word":"Researcher","meaning":{"en":"An agent for research jobs","tr":"Araştırma işleri için bir agent","fa":"یک ایجنت برای کارهای تحقیقی"}},{"word":"Draft","meaning":{"en":"Write a first version","tr":"İlk sürümü yaz","fa":"نسخه‌ی اول را بنویس"}},{"word":"Summarize","meaning":{"en":"Give the main points in short","tr":"Ana noktaları kısaca ver","fa":"نکته‌های اصلی را کوتاه بگو"}},{"word":"AI credits","meaning":{"en":"Your allowance for AI use on some plans","tr":"Bazı planlarda yapay zekâ kullanım hakkın","fa":"سهمیه‌ی استفاده از هوش مصنوعی در بعضی پلن‌ها"}},{"word":"AutoSave","meaning":{"en":"Saves your file automatically. Copilot in Excel needs it, so the file must be on OneDrive.","tr":"Dosyanı otomatik kaydeder. Excel'deki Copilot buna ihtiyaç duyar, bu yüzden dosya OneDrive'da olmalıdır.","fa":"فایلت را خودکار ذخیره می‌کند. Copilot در Excel به آن نیاز دارد، پس فایل باید در OneDrive باشد."}}],"prompts":[{"text":"Goal: Draft a short reply to this email.\nContext: The customer is waiting for a delivery date, and I am writing for the support team.\nSource: Use only the delivery date in the attached order sheet.\nExpectations: Under 80 words, polite and simple, with a subject line.","why":{"en":"It uses Microsoft's own four parts, and the source is your own file.","tr":"Microsoft'un kendi dört bölümünü kullanır ve kaynak senin dosyandır.","fa":"از چهار بخش خود مایکروسافت استفاده می‌کند و منبعش فایل خودت است."},"run":false},{"text":"Summarize this email thread for my manager.\nList the decisions, the open questions and who owns each one.\nUnder 100 words. Keep names, dates and numbers exactly as written.","why":{"en":"Copilot can work on a thread in Outlook, so you don't need to copy it anywhere.","tr":"Copilot, Outlook'ta e-posta zinciri üzerinde çalışabilir; onu bir yere kopyalaman gerekmez.","fa":"Copilot می‌تواند در Outlook روی رشته‌ی ایمیل کار کند، پس لازم نیست آن را جایی کپی کنی."},"run":false}],"fourParts":[{"part":"Goal","q":{"en":"What do you want it to do? This is the only part you must have.","tr":"Ne yapmasını istiyorsun? Şart olan tek bölüm budur.","fa":"می‌خواهی چه کاری بکند؟ این تنها بخش ضروری است."}},{"part":"Context","q":{"en":"Why do you need it, and who is involved?","tr":"Neden gerekiyor, kimler işin içinde?","fa":"چرا لازمش داری و چه کسانی درگیرند؟"}},{"part":"Source","q":{"en":"What information should it use?","tr":"Hangi bilgileri kullanmalı?","fa":"از چه اطلاعاتی استفاده کند؟"}},{"part":"Expectations","q":{"en":"How should it answer?","tr":"Nasıl yanıt vermeli?","fa":"چطور جواب بدهد؟"}}],"limits":[{"en":"Microsoft says Copilot can be wrong, and tells you to check its answers against trusted sources.","tr":"Microsoft, Copilot'un yanılabileceğini söylüyor ve yanıtlarını güvenilir kaynaklarla karşılaştırmanı istiyor.","fa":"مایکروسافت می‌گوید Copilot ممکن است اشتباه کند و از تو می‌خواهد جواب‌هایش را با منبع‌های معتبر مقایسه کنی."},{"en":"The same prompt can give different results, so expect some back and forth.","tr":"Aynı prompt farklı sonuçlar verebilir; birkaç kez gidip gelmeyi bekle.","fa":"یک پرامپت ممکن است نتیجه‌های متفاوتی بدهد، پس انتظار چند رفت‌وبرگشت را داشته باش."},{"en":"Home and work accounts have different data rules. Never assume one is like the other.","tr":"Ev ve iş hesaplarının veri kuralları farklıdır. Birini diğeri gibi sanma.","fa":"حساب شخصی و کاری قواعد متفاوتی برای داده‌ها دارند. فکر نکن مثل هم‌اند."}]},"claude":{"id":"claude","name":"Claude","lesson":5,"checkedOn":"2026-10-31","source":"OUTLINE.md section 2.9","line":{"en":"A general assistant for writing and for questions about documents you give it.","tr":"Yazı ve ona verdiğin belgeler hakkındaki sorular için genel bir asistan.","fa":"یک دستیار عمومی برای نوشتن و برای سؤال درباره‌ی سندهایی که به آن می‌دهی."},"what":{"en":"Claude is a general AI assistant made by the company Anthropic. You can use it in a browser or in its apps. It can answer questions, write and analyse text.","tr":"Claude, Anthropic şirketinin yaptığı genel bir yapay zekâ asistanıdır. Tarayıcıda ya da uygulamalarında kullanabilirsin. Soruları yanıtlayabilir, yazı yazabilir ve metin çözümleyebilir.","fa":"Claude یک دستیار عمومی هوش مصنوعی است که شرکت Anthropic آن را ساخته. می‌توانی در مرورگر یا اپلیکیشن‌هایش از آن استفاده کنی. می‌تواند به سؤال‌ها جواب بدهد، بنویسد و متن را تحلیل کند."},"teach":[{"en":"It reads a file you upload and answers about it in the same chat.","tr":"Yüklediğin dosyayı okur ve aynı sohbette onun hakkında yanıt verir.","fa":"فایلی را که آپلود می‌کنی می‌خواند و در همان چت درباره‌اش جواب می‌دهد.","ex":"+ then Add files or photos"},{"en":"A Project keeps one job's chats and files together.","tr":"Project, bir işin sohbetlerini ve dosyalarını bir arada tutar.","fa":"Project چت‌ها و فایل‌های یک کار را کنار هم نگه می‌دارد.","ex":"Projects"}],"good":[{"en":"Questions about long documents you upload","tr":"Yüklediğin uzun belgeler hakkında sorular","fa":"سؤال درباره‌ی سندهای طولانی‌ای که آپلود می‌کنی","ex":"What does this contract say about delivery?"},{"en":"Keeping documents for one job together in a Project","tr":"Bir işin belgelerini bir Project içinde bir arada tutmak","fa":"نگه داشتن سندهای یک کار در کنار هم در یک Project","ex":"One Project: price list, policy, FAQ"},{"en":"Drafting and editing text","tr":"Metin taslağı yazmak ve düzenlemek","fa":"نوشتن پیش‌نویس و ویرایش متن"},{"en":"Diagrams and simple charts in the chat","tr":"Sohbette şemalar ve basit grafikler","fa":"نمودار و چارت ساده در چت"}],"notBest":[{"en":"Photos and illustrations. Anthropic says Claude doesn't create them.","tr":"Fotoğraf ve illüstrasyon. Anthropic, Claude'un bunları üretmediğini söylüyor.","fa":"عکس و تصویرسازی. Anthropic می‌گوید Claude این‌ها را نمی‌سازد.","ex":"Need a photo? Use an image maker."},{"en":"Work inside your Gmail or Word. Look first at the assistant made for that place.","tr":"Gmail ya da Word içindeki işler. Önce o yer için yapılmış asistana bak.","fa":"کار داخل Gmail یا Word. اول سراغ دستیاری برو که برای همان‌جا ساخته شده.","ex":"Mail in Outlook? Look at Copilot."}],"start":[{"en":"Go to claude.ai, or open the app.","tr":"claude.ai adresine git ya da uygulamayı aç.","fa":"به claude.ai برو یا اپلیکیشن را باز کن."},{"en":"Sign up or log in. Anthropic says you must be at least 18 and in a supported location.","tr":"Kaydol ya da giriş yap. Anthropic, en az 18 yaşında olman ve desteklenen bir yerde bulunman gerektiğini söylüyor.","fa":"ثبت‌نام کن یا وارد شو. Anthropic می‌گوید باید دست‌کم ۱۸ ساله باشی و در منطقه‌ای باشی که پشتیبانی می‌شود."},{"en":"Type your message. Use + to add a file.","tr":"Mesajını yaz. Dosya eklemek için + düğmesini kullan.","fa":"پیامت را بنویس. برای اضافه کردن فایل از + استفاده کن."},{"en":"Ask about the file in the same chat.","tr":"Dosyayla ilgili soruları aynı sohbette sor.","fa":"سؤال‌های مربوط به فایل را در همان چت بپرس."}],"startNote":{"en":"There is a free plan with a usage limit that resets every few hours.","tr":"Birkaç saatte bir sıfırlanan kullanım sınırına sahip ücretsiz bir plan var.","fa":"یک پلن رایگان هست با محدودیت استفاده که هر چند ساعت یک بار از نو شروع می‌شود."},"words":[{"word":"+","meaning":{"en":"Add a file, or find more options","tr":"Dosya ekle ya da başka seçenekler bul","fa":"فایل اضافه کن یا گزینه‌های بیشتر را ببین"}},{"word":"Upload","meaning":{"en":"Send a file from your device to the tool","tr":"Cihazından araca dosya gönder","fa":"فایلی را از دستگاهت به ابزار بفرست"}},{"word":"Projects","meaning":{"en":"Separate workspaces with their own chats and documents","tr":"Kendi sohbetleri ve belgeleri olan ayrı çalışma alanları","fa":"فضاهای کاری جدا با چت‌ها و سندهای خودشان"}},{"word":"Web search","meaning":{"en":"Lets it look on the web. In some versions it does this by itself.","tr":"Web'de bakmasını sağlar. Bazı sürümlerde bunu kendiliğinden yapar.","fa":"اجازه می‌دهد در وب بگردد. در بعضی نسخه‌ها خودش این کار را می‌کند."}},{"word":"Incognito chat","meaning":{"en":"A chat that stays out of your history and isn't used for training. It is still kept for a time.","tr":"Geçmişinde görünmeyen ve eğitimde kullanılmayan sohbet. Yine de bir süre saklanır.","fa":"چتی که در تاریخچه‌ات نمی‌ماند و برای آموزش استفاده نمی‌شود. با این حال مدتی نگه داشته می‌شود."}},{"word":"Usage limit","meaning":{"en":"How much you can use it before you must wait","tr":"Beklemen gerekmeden önce ne kadar kullanabileceğin","fa":"تا چه اندازه می‌توانی از آن استفاده کنی تا مجبور به صبر شوی"}},{"word":"Privacy settings","meaning":{"en":"Where you choose how your chats may be used","tr":"Sohbetlerinin nasıl kullanılabileceğini seçtiğin yer","fa":"جایی که انتخاب می‌کنی چت‌هایت چطور استفاده شوند"}}],"prompts":[{"text":"Based only on the document I uploaded, list the five main points.\nFor each point, give the page or section.\nIf something is not in the document, write \"not in the document\".","why":{"en":"You can upload the document, and page numbers let you check each point.","tr":"Belgeyi yükleyebilirsin; sayfa numaraları her noktayı kontrol etmeni sağlar.","fa":"می‌توانی سند را آپلود کنی و شماره‌ی صفحه‌ها کمک می‌کنند هر نکته را بررسی کنی."},"run":false},{"text":"Here is my draft and a short sample of how I usually write.\nMake the draft clearer, but keep my style. Keep every number.\nThen list what you changed.\nDraft: [paste]   Sample: [paste]","why":{"en":"Your own sample gives it a style to follow. This works on other tools too.","tr":"Kendi örneğin ona izleyeceği bir üslup verir. Bu başka araçlarda da işe yarar.","fa":"نمونه‌ی خودت سبکی به آن می‌دهد که از آن پیروی کند. این روش در ابزارهای دیگر هم جواب می‌دهد."},"run":false}],"limits":[{"en":"Like any assistant, it can be wrong, and it can sound sure when it is wrong. Check every point against the page.","tr":"Her asistan gibi yanılabilir ve yanılırken de emin görünebilir. Her noktayı sayfayla karşılaştır.","fa":"مثل هر دستیاری ممکن است اشتباه کند و حتی وقتی اشتباه می‌کند مطمئن به نظر برسد. هر نکته را با صفحه مقایسه کن."},{"en":"\"Based only on\" makes guessing less likely. It doesn't stop it.","tr":"\"Based only on\" tahmin ihtimalini azaltır ama tamamen önlemez.","fa":"عبارت «Based only on» احتمال حدس زدن را کم می‌کند، ولی جلویش را نمی‌گیرد."},{"en":"An Incognito chat is still kept for a time, so it is not a place for secrets.","tr":"Incognito chat de bir süre saklanır, yani sırlar için bir yer değildir.","fa":"چت Incognito هم مدتی نگه داشته می‌شود، پس جای اطلاعات محرمانه نیست."}]},"midjourney":{"id":"midjourney","name":"Midjourney","lesson":8,"checkedOn":"2026-10-31","source":"OUTLINE.md section 2.9","line":{"en":"A paid tool only for making images, with its own way of writing prompts.","tr":"Yalnızca görsel üretmek için, kendine özgü prompt yazma biçimi olan ücretli bir araç.","fa":"یک ابزار پولی فقط برای ساختن تصویر، با روش خودش برای نوشتن پرامپت."},"what":{"en":"Midjourney is an AI tool made only for images and video, from the company Midjourney.","tr":"Midjourney, yalnızca görsel ve video için yapılmış bir yapay zekâ aracıdır; aynı adlı şirketin ürünüdür.","fa":"Midjourney یک ابزار هوش مصنوعی است که فقط برای تصویر و ویدیو ساخته شده و نام شرکت سازنده‌اش هم همین است."},"teach":[{"en":"It doesn't chat. You describe a picture, and it makes several versions.","tr":"Sohbet etmez. Bir görseli anlatırsın, o da birkaç sürüm üretir.","fa":"چت نمی‌کند. تصویری را توصیف می‌کنی و چند نسخه از آن می‌سازد.","ex":"a small red van, wide shot"},{"en":"Some settings go inside the prompt, after two dashes.","tr":"Bazı ayarlar prompt'un içine, iki çizgiden sonra yazılır.","fa":"بعضی تنظیم‌ها داخل پرامپت و بعد از دو خط تیره می‌آیند.","ex":"--ar 16:9 --no people"}],"good":[{"en":"Pictures with a strong look: illustration, mood, a visual idea","tr":"Güçlü bir görünümü olan görseller: illüstrasyon, atmosfer, görsel bir fikir","fa":"تصویرهایی با ظاهر قوی: تصویرسازی، حال‌وهوا، یک ایده‌ی تصویری","ex":"a watercolour poster idea for a cafe"},{"en":"Trying many versions of one idea","tr":"Bir fikrin birçok sürümünü denemek","fa":"امتحان کردن نسخه‌های زیاد از یک ایده","ex":"Vary: a little different or very different"},{"en":"Exact control of shape with `--ar`","tr":"`--ar` ile görsel biçimini tam belirlemek","fa":"تعیین دقیق شکل کادر با `--ar`"}],"notBest":[{"en":"Text answers, emails or research. It is not a chat assistant for those.","tr":"Metin yanıtları, e-postalar ya da araştırma. Bunlar için bir sohbet asistanı değildir.","fa":"جواب متنی، ایمیل یا تحقیق. برای این کارها دستیار چت نیست.","ex":"Emails? Use a text assistant."},{"en":"Secret designs. Images are public by default, and hiding them needs a higher plan.","tr":"Gizli tasarımlar. Görseller varsayılan olarak herkese açıktır; gizlemek için üst plan gerekir.","fa":"طرح‌های محرمانه. تصویرها به‌طور پیش‌فرض عمومی‌اند و برای پنهان کردنشان پلن بالاتری لازم است.","ex":"Secret product? Don't describe it."},{"en":"Learners with no budget. You need a paid plan to create. Try the same picture words in a chat tool.","tr":"Bütçesi olmayanlar. Görsel üretmek için ücretli plan gerekir. Aynı görsel kelimelerini bir sohbet aracında dene.","fa":"کسی که بودجه ندارد. برای ساختن تصویر پلن پولی لازم است. همین کلمه‌های تصویری را در یک ابزار چت امتحان کن.","ex":"No plan? Same words in a chat tool."}],"start":[{"en":"Go to midjourney.com and log in.","tr":"midjourney.com adresine git ve giriş yap.","fa":"به midjourney.com برو و وارد شو."},{"en":"Choose a plan. You must subscribe before you can create.","tr":"Bir plan seç. Üretmeden önce abone olman gerekir.","fa":"یک پلن انتخاب کن. پیش از ساختن تصویر باید اشتراک بگیری."},{"en":"Open Create. Type your prompt in the Imagine bar at the top and press Enter.","tr":"Create'i aç. Üstteki Imagine çubuğuna prompt'unu yaz ve Enter'a bas.","fa":"Create را باز کن. پرامپتت را در نوار Imagine در بالا بنویس و Enter را بزن."},{"en":"Click an image to see more options.","tr":"Daha fazla seçenek görmek için bir görsele tıkla.","fa":"برای دیدن گزینه‌های بیشتر روی یک تصویر کلیک کن."}],"startNote":{"en":"This course does not need a Midjourney plan. Any image from this course is labelled \"example image\". None was made with Midjourney.","tr":"Bu kurs için Midjourney planı gerekmez. Bu kursun görsellerinde \"example image\" yazar. Hiçbiri Midjourney ile yapılmadı.","fa":"برای این دوره پلن Midjourney لازم نیست. روی هر تصویری از این دوره نوشته شده «example image». هیچ‌کدام با Midjourney ساخته نشده‌اند."},"words":[{"word":"Create","meaning":{"en":"The page where you make images","tr":"Görsel ürettiğin sayfa","fa":"صفحه‌ای که در آن تصویر می‌سازی"}},{"word":"Imagine bar","meaning":{"en":"The box where you type the prompt","tr":"Prompt'u yazdığın kutu","fa":"کادری که پرامپت را در آن می‌نویسی"}},{"word":"Organize","meaning":{"en":"The page where you find and sort your images","tr":"Görsellerini bulup düzenlediğin sayfa","fa":"صفحه‌ای که تصویرهایت را در آن پیدا و مرتب می‌کنی"}},{"word":"Vary (subtle or strong)","meaning":{"en":"Make new versions, a little different or very different","tr":"Biraz ya da çok farklı yeni sürümler üret","fa":"نسخه‌های جدید بساز، کمی متفاوت یا خیلی متفاوت"}},{"word":"Stealth","meaning":{"en":"Keeps new images out of the public gallery. Only on higher plans.","tr":"Yeni görselleri herkese açık galeriden uzak tutar. Yalnızca üst planlarda.","fa":"تصویرهای جدید را از گالری عمومی دور نگه می‌دارد. فقط در پلن‌های بالاتر."}},{"word":"--ar 16:9","meaning":{"en":"Sets the aspect ratio: width compared with height. Write it at the end of the prompt. Square (1:1) is the default.","tr":"En-boy oranını belirler: genişliğin yüksekliğe oranı. Prompt'un sonuna yaz. Varsayılan kare (1:1) biçimdir.","fa":"نسبت تصویر را تعیین می‌کند: عرض در مقایسه با ارتفاع. آن را آخر پرامپت بنویس. حالت پیش‌فرض مربع (1:1) است."}},{"word":"--no people","meaning":{"en":"Tells it what you don't want","tr":"Ne istemediğini söyler","fa":"می‌گوید چه چیزی نمی‌خواهی"}}],"prompts":[{"text":"a small white ceramic coffee cup on a wooden table, morning light from a window, close-up, photorealistic --ar 16:9","why":{"en":"A rich description, not an instruction. The shape goes at the end.","tr":"Talimat değil, zengin bir betimleme. Biçim sonda yer alır.","fa":"توصیفی پربار، نه دستور. شکل کادر در آخر می‌آید."},"run":false},{"text":"a quiet meeting room with a large window, soft evening light, watercolour illustration, wide shot --ar 3:2 --no people","why":{"en":"People are removed with `--no`, because writing \"no people\" in the description may still bring people.","tr":"İnsanlar `--no` ile çıkarılır, çünkü betimlemede \"no people\" yazmak yine de insan getirebilir.","fa":"آدم‌ها با `--no` حذف می‌شوند، چون نوشتن «no people» در توصیف باز هم ممکن است آدم بیاورد."},"run":false}],"limits":[{"en":"Your images may be public. Don't describe a secret product or a real customer.","tr":"Görsellerin herkese açık olabilir. Gizli bir ürünü ya da gerçek bir müşteriyi anlatma.","fa":"تصویرهایت ممکن است عمومی باشند. محصول محرمانه یا مشتری واقعی را توصیف نکن."},{"en":"The same prompt gives different pictures. Check hands, faces, text and product details.","tr":"Aynı prompt farklı görseller verir. Elleri, yüzleri, yazıları ve ürün ayrıntılarını kontrol et.","fa":"یک پرامپت تصویرهای متفاوتی می‌دهد. دست‌ها، چهره‌ها، نوشته‌ها و جزئیات محصول را بررسی کن."},{"en":"Before business use, read its terms yourself. They differ by plan and company size. This course gives no legal advice.","tr":"İş için kullanmadan önce koşullarını kendin oku. Plana ve şirket büyüklüğüne göre değişir. Bu kurs hukuki tavsiye vermez.","fa":"پیش از استفاده‌ی کاری، شرایطش را خودت بخوان. بسته به پلن و اندازه‌ی شرکت فرق دارد. این دوره مشاوره‌ی حقوقی نمی‌دهد."}]},"perplexity":{"id":"perplexity","name":"Perplexity","lesson":12,"checkedOn":"2026-10-31","source":"OUTLINE.md section 2.9","line":{"en":"AI search. It answers with numbered links, so you can open the sources.","tr":"Yapay zekâlı arama. Numaralı bağlantılarla yanıt verir, böylece kaynakları açabilirsin.","fa":"جست‌وجوی هوش مصنوعی. با لینک‌های شماره‌دار جواب می‌دهد تا بتوانی منبع‌ها را باز کنی."},"what":{"en":"Perplexity is an AI search tool. You ask a question as you would ask a person.","tr":"Perplexity, yapay zekâlı bir arama aracıdır. Bir insana sorar gibi soru sorarsın.","fa":"Perplexity یک ابزار جست‌وجوی هوش مصنوعی است. طوری سؤال می‌پرسی که انگار از یک آدم می‌پرسی."},"teach":[{"en":"It searches first and then writes, so the answer has numbered links you can open.","tr":"Önce arar, sonra yazar; bu yüzden yanıtta açabileceğin numaralı bağlantılar olur.","fa":"اول می‌گردد و بعد می‌نویسد، پس جوابش لینک‌های شماره‌داری دارد که می‌توانی بازشان کنی.","ex":"... last up to 50,000 hours [1]"},{"en":"It still writes likely words about those pages, so its sentence may differ from the page.","tr":"Yine de bu sayfalar hakkında olası kelimeler yazar; cümlesi sayfadakinden farklı olabilir.","fa":"باز هم درباره‌ی آن صفحه‌ها کلمه‌های محتمل می‌نویسد، پس ممکن است جمله‌اش با صفحه فرق داشته باشد.","ex":"Open [1]. Does it say that?"}],"good":[{"en":"A quick overview, with links to start from","tr":"Başlangıç için bağlantılarla birlikte hızlı bir genel bakış","fa":"یک نگاه کلی سریع، با لینک‌هایی برای شروع","ex":"What changed in EU packaging rules this year?"},{"en":"Finding the right English words for a topic","tr":"Bir konunun doğru İngilizce kelimelerini bulmak","fa":"پیدا کردن کلمه‌های انگلیسی درست برای یک موضوع","ex":"What is the English term for this part?"},{"en":"Follow-up questions on the same topic","tr":"Aynı konuda ek sorular","fa":"پرسیدن سؤال‌های بعدی درباره‌ی همان موضوع"}],"notBest":[{"en":"A final answer without opening the links. A link doesn't prove the answer.","tr":"Bağlantıları açmadan nihai yanıt almak. Bağlantı, yanıtı kanıtlamaz.","fa":"جواب نهایی بدون باز کردن لینک‌ها. لینک ثابت نمی‌کند که جواب درست است.","ex":"Open the link first."},{"en":"Writing a long email in your voice. A text assistant suits that better.","tr":"Kendi üslubunla uzun bir e-posta yazmak. Bunun için metin asistanı daha uygundur.","fa":"نوشتن ایمیل طولانی با لحن خودت. دستیار متنی برای این کار مناسب‌تر است.","ex":"Long email? Use a text assistant."}],"start":[{"en":"Go to perplexity.ai.","tr":"perplexity.ai adresine git.","fa":"به perplexity.ai برو."},{"en":"Type a question, as you would ask a person.","tr":"Bir insana sorar gibi sorunu yaz.","fa":"سؤالت را طوری بنویس که انگار از یک آدم می‌پرسی."},{"en":"Read the answer and press a number to see its source.","tr":"Yanıtı oku ve kaynağını görmek için bir numaraya bas.","fa":"جواب را بخوان و برای دیدن منبع روی یک شماره بزن."},{"en":"Open the page. Does it really say that?","tr":"Sayfayı aç. Gerçekten bunu mu söylüyor?","fa":"صفحه را باز کن. واقعاً همین را می‌گوید؟"}],"startNote":{"en":"The free plan covers basic search. Stronger modes have limits, and these change.","tr":"Ücretsiz plan temel aramayı kapsar. Daha güçlü modların sınırları vardır ve bunlar değişir.","fa":"پلن رایگان جست‌وجوی پایه را پوشش می‌دهد. حالت‌های قوی‌تر محدودیت دارند و این محدودیت‌ها تغییر می‌کنند."},"words":[{"word":"Citation","meaning":{"en":"A numbered link to a source","tr":"Bir kaynağa giden numaralı bağlantı","fa":"لینک شماره‌دار به یک منبع"}},{"word":"Search","meaning":{"en":"The normal way to ask","tr":"Normal soru sorma yolu","fa":"روش معمولی پرسیدن"}},{"word":"Deep Research","meaning":{"en":"Runs many searches and writes a longer report, in a few minutes","tr":"Birçok arama yapar ve birkaç dakikada daha uzun bir rapor yazar","fa":"جست‌وجوهای زیادی انجام می‌دهد و در چند دقیقه گزارش طولانی‌تری می‌نویسد"}},{"word":"Follow-up","meaning":{"en":"Your next question, on the same topic","tr":"Aynı konudaki bir sonraki sorun","fa":"سؤال بعدی‌ات درباره‌ی همان موضوع"}},{"word":"Library","meaning":{"en":"Your earlier questions and answers","tr":"Önceki soruların ve yanıtların","fa":"سؤال‌ها و جواب‌های قبلی‌ات"}},{"word":"Export","meaning":{"en":"Save an answer as a file, such as PDF","tr":"Bir yanıtı PDF gibi bir dosya olarak kaydet","fa":"ذخیره‌ی جواب به‌صورت فایل، مثلاً PDF"}},{"word":"Anyone with the link","meaning":{"en":"A sharing choice: people with the link can see it","tr":"Paylaşım seçeneği: bağlantıya sahip olanlar görebilir","fa":"یک گزینه‌ی اشتراک: هر کس لینک را داشته باشد می‌تواند ببیند"}}],"prompts":[{"text":"What is the usual lifespan of LED lamps in a hotel?\nUse the documents of manufacturers if you can.\nGive a short answer. After each claim, show which source supports it.","why":{"en":"It searches live, and each claim comes with a number you can open.","tr":"Canlı arama yapar ve her iddia, açabileceğin bir numarayla gelir.","fa":"زنده جست‌وجو می‌کند و هر ادعا با شماره‌ای می‌آید که می‌توانی بازش کنی."},"run":false},{"text":"Look at the sources in your last answer.\nFor each one, give the publisher and the date.\nWhich are independent, and which are selling something?","why":{"en":"A follow-up keeps the topic. It starts your own check, but it can be wrong too, so still open the pages.","tr":"Ek soru konuyu korur. Kendi kontrolünü başlatır ama o da yanlış olabilir, bu yüzden sayfaları yine aç.","fa":"سؤال بعدی موضوع را حفظ می‌کند. بررسی خودت را شروع می‌کند، ولی آن هم ممکن است اشتباه باشد، پس باز هم صفحه‌ها را باز کن."},"run":false}],"limits":[{"en":"The answer can say something the source doesn't say. Tests of AI search tools have found wrong citations, so open the page.","tr":"Yanıt, kaynağın söylemediği bir şeyi söyleyebilir. Yapay zekâlı arama araçları üzerine yapılan testlerde yanlış kaynak gösterme bulundu. Bu yüzden sayfayı aç.","fa":"جواب ممکن است چیزی بگوید که منبع نگفته. در آزمایش‌هایی روی ابزارهای جست‌وجوی هوش مصنوعی ارجاع‌های اشتباه پیدا شده، پس صفحه را باز کن."},{"en":"Its sources can be weak: a forum, or a seller's own blog. Lesson 14 shows how to judge them.","tr":"Kaynakları zayıf olabilir: bir forum ya da satıcının kendi blogu. Ders 14 bunları nasıl değerlendireceğini gösterir.","fa":"منبع‌هایش ممکن است ضعیف باشند: یک فروم یا وبلاگ خود فروشنده. درس ۱۴ نشان می‌دهد چطور آن‌ها را بسنجی."},{"en":"Check who can see an answer before you share it. Keep private details out of your question.","tr":"Bir yanıtı paylaşmadan önce kimlerin görebileceğini kontrol et. Sorunda özel bilgi kullanma.","fa":"پیش از اشتراک‌گذاری یک جواب، ببین چه کسانی می‌توانند آن را ببینند. اطلاعات خصوصی را در سؤالت نیاور."}]}},"shortCards":{"deepseek":{"name":"DeepSeek","card":{"en":"DeepSeek is another general AI assistant, and you may hear about it at work. Its privacy policy says personal data is stored in China. Read the privacy page of any tool, and follow the same rule: nothing private goes in.","tr":"DeepSeek başka bir genel yapay zekâ asistanıdır; iş yerinde adını duyabilirsin. Gizlilik politikası, kişisel verilerin Çin'de saklandığını söylüyor. Her aracın gizlilik sayfasını oku ve aynı kurala uy: özel bilgi girme.","fa":"DeepSeek هم یک دستیار عمومی هوش مصنوعی است و شاید در محل کار اسمش را بشنوی. سیاست حفظ حریم خصوصی‌اش می‌گوید داده‌های شخصی در چین نگه داشته می‌شوند. صفحه‌ی حریم خصوصی هر ابزاری را بخوان و همان قاعده را رعایت کن: هیچ چیز خصوصی را وارد نکن."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
